def solve(c, a, n):
    print(f"{c}/(x - ({a}))**{n} at x = {a}")
    if c > 0:
        right = "oo"
    else:
        right = "-oo"
    if (n % 2 == 0) == (c > 0):
        left = "oo"
    else:
        left = "-oo"
    print(f"  right: {right}, left: {left}")
    if left == right:
        print(f"  both sides agree: the limit is {right}")
    else:
        print("  the sides differ: no two-sided infinite limit")
    print(f"  vertical asymptote x = {a}")
k = int(input())
for i in range(k):
    c = int(input())
    a = int(input())
    n = int(input())
    solve(c, a, n)

from fractions import Fraction
def solve(p, q):
    print(f"p = {p}, q = {q}")
    dp = len(p) - 1
    dq = len(q) - 1
    print(f"  degrees {dp} and {dq}, leading coefficients {p[0]} and {q[0]}")
    if dp == dq:
        print(f"  equal degrees: the limit is {Fraction(p[0], q[0])}")
    elif dp < dq:
        print("  bigger bottom: the limit is 0")
    elif (p[0] > 0) == (q[0] > 0):
        print("  bigger top: the limit is oo")
    else:
        print("  bigger top: the limit is -oo")
def read_poly():
    n = int(input())
    coeffs = []
    for i in range(n):
        coeffs.append(int(input()))
    return coeffs
k = int(input())
for i in range(k):
    p = read_poly()
    q = read_poly()
    solve(p, q)

