def solve(label, k, b):
    print(label)
    for n in [2, 5, 10, 30, 60]:
        print(f"  n = {n}: n**{k} = {n ** k}, {b}**n = {b ** n}, exponential ahead: {b ** n > n ** k}")
    last = 0
    for n in range(2, 1001):
        if n ** k >= b ** n:
            last = n
    if last == 0:
        print("  the exponential is ahead at every n from 2 to 1000")
    else:
        print(f"  the last n where n**{k} >= {b}**n is {last}, so {b}**n leads from {last + 1} on")
solve("Case 1 · a square against a doubling", 2, 2)
solve("Case 2 · a big power against a doubling", 10, 2)
solve("Case 3 · a tie: n**3 against 3**n", 3, 3)
solve("Case 4 · never close: n against 2**n", 1, 2)

